<main class="wrap">
  <h1>Pocket Garden</h1>
  <p class="lead">Pick plants for your garden and mark the ones you've planted.</p>
  <p class="note"><strong>Heads up:</strong> your choices reset when you reload this page.</p>

  <fieldset class="filters">
    <legend>Show plants</legend>
    <div class="filter-row">
      <button type="button" class="filter" data-filter="all" aria-pressed="true">All plants</button>
      <button type="button" class="filter" data-filter="sun" aria-pressed="false">Loves sun</button>
      <button type="button" class="filter" data-filter="shade" aria-pressed="false">Likes shade</button>
    </div>
  </fieldset>

  <p class="status" id="status" role="status" aria-live="polite">Showing 3 of 3 plants.</p>

  <ul class="grid" id="grid">
    <li class="card" data-light="sun">
      <span class="icon" aria-hidden="true">🌿</span>
      <h2>Basil</h2>
      <span class="tag">☀ Loves sun</span>
      <p>A fragrant herb that thrives in warm, bright spots and plenty of light.</p>
      <button type="button" class="plant-btn" aria-pressed="false">Mark as planted<span class="sr-only">: Basil</span></button>
    </li>
    <li class="card" data-light="sun">
      <span class="icon" aria-hidden="true">🌻</span>
      <h2>Sunflower</h2>
      <span class="tag">☀ Loves sun</span>
      <p>Tall and cheerful, it follows the sun and wants a full day of bright light.</p>
      <button type="button" class="plant-btn" aria-pressed="false">Mark as planted<span class="sr-only">: Sunflower</span></button>
    </li>
    <li class="card" data-light="shade">
      <span class="icon" aria-hidden="true">🍃</span>
      <h2>Mint</h2>
      <span class="tag">☂ Likes shade</span>
      <p>A hardy herb that is happy in cooler, shadier corners of the garden.</p>
      <button type="button" class="plant-btn" aria-pressed="false">Mark as planted<span class="sr-only">: Mint</span></button>
    </li>
  </ul>
</main>

<script>
(function () {
  var filterButtons = document.querySelectorAll('.filter');
  var cards = document.querySelectorAll('.card');
  var status = document.getElementById('status');

  function applyFilter(value) {
    var shown = 0;
    cards.forEach(function (card) {
      var match = value === 'all' || card.dataset.light === value;
      card.hidden = !match;
      if (match) shown++;
    });
    filterButtons.forEach(function (btn) {
      btn.setAttribute('aria-pressed', String(btn.dataset.filter === value));
    });
    status.textContent = 'Showing ' + shown + ' of ' + cards.length + ' plants.';
  }

  filterButtons.forEach(function (btn) {
    btn.addEventListener('click', function () { applyFilter(btn.dataset.filter); });
  });

  cards.forEach(function (card) {
    var btn = card.querySelector('.plant-btn');
    var name = card.querySelector('h2').textContent;
    btn.addEventListener('click', function () {
      var planted = btn.getAttribute('aria-pressed') !== 'true';
      btn.setAttribute('aria-pressed', String(planted));
      btn.innerHTML = (planted ? 'Planted' : 'Mark as planted') +
        '<span class="sr-only">: ' + name + '</span>';
      card.classList.toggle('is-planted', planted);
    });
  });
})();
</script>
